INSERT INTO `tblitemable` VALUES (1,1,'proposal','teste','teste',2.00,3.00,'',1),(2,1,'proposal','Chat Vya.Digital','Plataforma de atendimento multicanal, que permite: (i) a gestão do atendimento ao cliente de forma unificada; (ii) a organização de equipe de atendentes com categorização de departamentos/setores; (iii) o atendimento unificado com o envio/recebimento de mensagens com ou sem anexo para as plataformas WhatsApp, Facebook, Telegram e sites corporativos; e (iv) que um mesmo número de telefone seja acessado simultaneamente por mais de um atendente.',1.00,119.90,'Licença',2),(3,1,'proposal','Voicebot IA','Sistema de atendimento ao cliente em canais de voz, automatizado e customizado, com integração de Inteligência Artificial para personalizar as interações com os clientes.',1.00,1650.00,'Licença',3);
