INSERT INTO `tblnotes` VALUES (1,85,'ticket','VPN criadas.<br />\nComunicação enviada em 09/09/2025 as 16:00 hs',NULL,14,'2025-01-09 17:01:34'),(2,94,'ticket','Favor confirmar duas informações:<br />\n<br />\n1) Estamos falando de Sysneis.com.br?<br />\n<br />\n2) Se os IPs são esses:<br />\nPaschoalotto:<br />\n <br />\nIPs Públicos Matriz Bauru:<br />\n204.225.42.0/23<br />\n <br />\nIPs Públicos Ribeirão Preto:<br />\n187.72.226.113/29<br />\n200.245.124.2/28<br />\n <br />\nIPs Públicos Marília:<br />\n189.2.139.176/28         <br />\n187.51.144.120/29<br />\n',NULL,1,'2025-01-13 10:59:29'),(3,1,'lead','Operação de 1000 boletos por mês.<br />\nRealizam cobrança para varejo, destacando setores de Confecções, Calçados, Supermercados e Distribuidoras.<br />\nHoje enviam boletos por e-mail, mas querem enviar por Wpp.<br />\nUtilizam CRM/ERP (Virtua Software https://virtuasoftware.com.br/)<br />\nAffonso: Encaminhei e-mail para virtua@virtuasoftware.com.br perguntando sobre documentação aberta de API.<br />\nInformou que quando registra um boleto no sistema da Virtua, pode disparar em massa ou gravar em uma pasta com informações que podem ser utilizadas para disparar em uma outra ferramenta externa.',NULL,9,'2025-01-24 10:02:22'),(4,4,'lead','Correspondente Bancário<br />\r\n<br />\r\nPerfil da Operação: Call Center com automação<br />\r\n<br />\r\nTecnologias e Ferramentas Atuais:<br />\r\nDiscador: 3C (sem objeções ao uso atual)<br />\r\nURA Reversa: PegTech, com disparo de WhatsApp utilizando um código Python (não oficial do WhatsApp).<br />\r\n<br />\r\nVolumetria Atual:<br />\r\nDiscadoras: 3 mil ligações/dia (2 discadoras em operação).<br />\r\nURA Reversa: 10 mil ligações/dia (3 robôs em operação).<br />\r\nEquipe Humana: 8 operadores humanos.<br />\r\n<br />\r\nDemandas e Problemas Identificados:<br />\r\nNecessidade de gerenciar dois fornecedores distintos com dados desintegrados e incongruentes.<br />\r\nDados gerados pela URA Reversa são ruins e exigem análises manuais do cliente.<br />\r\nNecessidade de integração e eficiência:<br />\r\nInteresse em uma solução unificada para substituir os dois fornecedores e centralizar as operações.<br />\r\n<br />\r\nOutras demandas:<br />\r\nDisparo de SMS e E-mail.<br />\r\nInteresse em transbordo para WhatsApp (provavelmente de maneira oficial para maior conformidade).<br />\r\n<br />\r\nOportunidade para Vya.Digital:<br />\r\nSubstituir os fornecedores atuais e oferecer soluções integradas que centralizem as operações e eliminem as dificuldades com dados inconsistentes e análises manuais.',NULL,9,'2025-01-24 14:14:11'),(5,5,'lead','Interesse em ativar Wpp Oficial na Meta e 8 licenças de Chat para seus atendentes.',NULL,9,'2025-01-24 16:49:12'),(6,135,'ticket','Documentação Ajuda atualizada https://ajuda.vya.digital/books/paschoalotto/page/exportacao-de-dados-paschoalotto',NULL,5,'2025-01-28 07:36:27'),(7,135,'ticket','Geovana, bom dia.<br />\n<br />\nEstamos pensando em seguir a seguinte logica:<br />\n<br />\nQuando o nome da campanha conter  \"[IA]\" o nome do fornecedor será VYA IA, caso contrario será VYA.<br />\n<br />\nDessa forma ficará automatico na alteração do nome, senao teremos de efetuar uma alteração no script toda vez que inserirmos uma campanha nova.<br />\n<br />\nPodemos seguir?',NULL,5,'2025-01-28 08:48:50'),(8,7,'lead','Tomador de decisão: Dr. Matheus:  matheus@unimedssp.coop.br',NULL,9,'2025-01-29 18:47:15'),(9,7,'lead','Reunião agendada para ativação de testes de Chat e Journey.','2025-01-30 10:30:00',9,'2025-01-30 11:05:03'),(11,135,'ticket','Tarefas finalizadas, pode comunicar o cliente',NULL,5,'2025-01-30 12:22:46'),(12,207,'ticket','Aguardando resposta do Edson sobre a API',NULL,5,'2025-02-03 10:15:22'),(13,275,'ticket','The hotmail.com server blocked this message from being delivered. While we won\'t try to send this message again, we will attempt to send new messages to this address in the future.<br />\n<br />\nYou can view all addresses in your Blocks suppression group. Learn more.<br />\n<br />\nFull response from the hotmail.com server:<br />\n<br />\n550 5.7.509 Access denied, sending domain [GRUPOSC.COM.BR] does not pass DMARC verification and has a DMARC policy of reject. [SA1PR20MB6029.namprd20.prod.outlook.com 2025-02-05T18:53:08.940Z 08DD4435E87BFDBF] [BN8PR07CA0032.namprd07.prod.outlook.com 2025-02-05T18:53:08.953Z 08DD446BE8A407A1] [BL02EPF0001A0FE.namprd03.prod.outlook.com 2025-02-05T18:53:08.947Z 08DD3F4B38C1ABA7]',NULL,5,'2025-02-07 09:37:35'),(14,572,'ticket','<br />\n 20/02 10h29 - sinalização via whatsapp para a Priscila (Coordenadora de desenvolvimento de sistemas), questionado sobre a atualização dos dados de todos os clientes com esse cenário<br />\n<br />\n20/02 10h40 - formalização feita via e-mail',NULL,12,'2025-02-20 15:54:00'),(15,571,'ticket','20/02 10h29 - sinalização via whatsapp para a Priscila (Coordenadora de desenvolvimento de sistemas), questionado sobre a atualização dos dados de todos os clientes com esse cenário<br />\n<br />\n20/02 10h40 - formalização feita via e-mail',NULL,12,'2025-02-20 15:55:12'),(16,668,'ticket','20/02 16h25 - ajustes de frases solicitados na Meta, aguardando prazo de 24 horas de analise',NULL,12,'2025-02-20 16:25:46'),(17,7,'lead','Pasta do Cliente: https://drive.google.com/drive/folders/10rEupcYQT6LgZkGAv5fW_XSWEEf5tglN?usp=drive_link',NULL,9,'2025-02-21 10:00:06'),(18,13,'lead','Pasta do Cliente: https://drive.google.com/drive/folders/1AaWVf57LLzDhtjT7bGu2ZFeAIfylpnx1?usp=sharing',NULL,9,'2025-03-03 17:13:20'),(19,25,'customer','Correspondente Bancário<br />\r\n<br />\r\nPerfil da Operação: Call Center com automação<br />\r\n<br />\r\nTecnologias e Ferramentas Atuais:<br />\r\nDiscador: 3C (sem objeções ao uso atual)<br />\r\nURA Reversa: PegTech, com disparo de WhatsApp utilizando um código Python (não oficial do WhatsApp).<br />\r\n<br />\r\nVolumetria Atual:<br />\r\nDiscadoras: 3 mil ligações/dia (2 discadoras em operação).<br />\r\nURA Reversa: 10 mil ligações/dia (3 robôs em operação).<br />\r\nEquipe Humana: 8 operadores humanos.<br />\r\n<br />\r\nDemandas e Problemas Identificados:<br />\r\nNecessidade de gerenciar dois fornecedores distintos com dados desintegrados e incongruentes.<br />\r\nDados gerados pela URA Reversa são ruins e exigem análises manuais do cliente.<br />\r\nNecessidade de integração e eficiência:<br />\r\nInteresse em uma solução unificada para substituir os dois fornecedores e centralizar as operações.<br />\r\n<br />\r\nOutras demandas:<br />\r\nDisparo de SMS e E-mail.<br />\r\nInteresse em transbordo para WhatsApp (provavelmente de maneira oficial para maior conformidade).<br />\r\n<br />\r\nOportunidade para Vya.Digital:<br />\r\nSubstituir os fornecedores atuais e oferecer soluções integradas que centralizem as operações e eliminem as dificuldades com dados inconsistentes e análises manuais.',NULL,9,'2025-01-24 14:14:11'),(20,16,'lead','Pasta do Cliente: https://drive.google.com/drive/folders/1UIWMf6JYKacFlwHYUrLTvhcxfJEZoRTn?usp=sharing',NULL,9,'2025-03-21 09:35:21'),(21,1733,'ticket','O evolution não foi instalado devido a erro no portainer ao criar stack com git.',NULL,14,'2025-04-01 11:05:04'),(22,17,'lead','Contrato em assinatura',NULL,9,'2025-04-11 18:41:25'),(23,2202,'ticket','Equipe comercial assumiu.',NULL,5,'2025-08-27 09:38:07'),(24,2207,'ticket','Acao : 115426',NULL,5,'2025-08-29 17:52:09');
